begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to authenticated;
grant execute on all functions in schema extensions to authenticated;
select no_plan();
insert into public.organizations(id,name,slug) values('f0000000-0000-4000-8000-000000000001','Safety 1','safety-1');
insert into public.organization_settings(organization_id) values('f0000000-0000-4000-8000-000000000001');
insert into public.organizations(id,name,slug) values('f0000000-0000-4000-8000-000000000002','Safety 2','safety-2');
insert into public.organization_settings(organization_id) values('f0000000-0000-4000-8000-000000000002');
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,aud,role) values('f1000000-0000-4000-8000-000000000001','safety-1@example.test',now(),'{}','{}','authenticated','authenticated');
insert into public.profiles(id,auth_user_id,organization_id,display_name,email,status) values('f2000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','f0000000-0000-4000-8000-000000000001','Safety 1','safety-1@example.test','active');
