insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,aud,role) values('f1000000-0000-4000-8000-000000000002','safety-2@example.test',now(),'{}','{}','authenticated','authenticated');
insert into public.profiles(id,auth_user_id,organization_id,display_name,email,status) values('f2000000-0000-4000-8000-000000000002','f1000000-0000-4000-8000-000000000002','f0000000-0000-4000-8000-000000000001','Safety 2','safety-2@example.test','active');
insert into public.roles(id,organization_id,name,system_key) values('f3000000-0000-4000-8000-000000000002','f0000000-0000-4000-8000-000000000001','Safety role 2','employee');
insert into public.user_roles(profile_id,role_id,organization_id) values('f2000000-0000-4000-8000-000000000002','f3000000-0000-4000-8000-000000000002','f0000000-0000-4000-8000-000000000001');
insert into public.role_permissions(role_id,permission_key) values('f3000000-0000-4000-8000-000000000002','messages.use');
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,aud,role) values('f1000000-0000-4000-8000-000000000003','safety-3@example.test',now(),'{}','{}','authenticated','authenticated');
insert into public.profiles(id,auth_user_id,organization_id,display_name,email,status) values('f2000000-0000-4000-8000-000000000003','f1000000-0000-4000-8000-000000000003','f0000000-0000-4000-8000-000000000001','Safety 3','safety-3@example.test','active');
insert into public.user_roles(profile_id,role_id,organization_id) values('f2000000-0000-4000-8000-000000000003','f3000000-0000-4000-8000-000000000002','f0000000-0000-4000-8000-000000000001');
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,aud,role) values('f1000000-0000-4000-8000-000000000004','safety-4@example.test',now(),'{}','{}','authenticated','authenticated');
insert into public.profiles(id,auth_user_id,organization_id,display_name,email,status) values('f2000000-0000-4000-8000-000000000004','f1000000-0000-4000-8000-000000000004','f0000000-0000-4000-8000-000000000002','Safety 4','safety-4@example.test','active');
insert into public.roles(id,organization_id,name,system_key) values('f3000000-0000-4000-8000-000000000004','f0000000-0000-4000-8000-000000000002','Safety role 4','super_admin');
insert into public.user_roles(profile_id,role_id,organization_id) values('f2000000-0000-4000-8000-000000000004','f3000000-0000-4000-8000-000000000004','f0000000-0000-4000-8000-000000000002');
insert into public.role_permissions(role_id,permission_key) values('f3000000-0000-4000-8000-000000000004','messages.use');
insert into public.conversations(id,organization_id,type,name,created_by) values('f4000000-0000-4000-8000-000000000001','f0000000-0000-4000-8000-000000000001','direct','Safety 1','f2000000-0000-4000-8000-000000000002');
insert into public.conversation_members(conversation_id,profile_id,organization_id) values('f4000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000002','f0000000-0000-4000-8000-000000000001');
insert into public.conversation_members(conversation_id,profile_id,organization_id) values('f4000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000003','f0000000-0000-4000-8000-000000000001');
insert into public.messages(id,organization_id,conversation_id,sender_id,body) values('f5000000-0000-4000-8000-000000000001','f0000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000003','Review this message 1');
insert into public.conversations(id,organization_id,type,name,created_by) values('f4000000-0000-4000-8000-000000000002','f0000000-0000-4000-8000-000000000001','group','Safety 2','f2000000-0000-4000-8000-000000000002');
insert into public.conversation_members(conversation_id,profile_id,organization_id) values('f4000000-0000-4000-8000-000000000002','f2000000-0000-4000-8000-000000000002','f0000000-0000-4000-8000-000000000001');
insert into public.conversation_members(conversation_id,profile_id,organization_id) values('f4000000-0000-4000-8000-000000000002','f2000000-0000-4000-8000-000000000003','f0000000-0000-4000-8000-000000000001');
insert into public.messages(id,organization_id,conversation_id,sender_id,body) values('f5000000-0000-4000-8000-000000000002','f0000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000002','f2000000-0000-4000-8000-000000000003','Review this message 2');
insert into public.message_attachments(organization_id,conversation_id,message_id,uploaded_by,storage_path,original_name,mime_type,size_bytes)
select organization_id,conversation_id,id,sender_id,organization_id::text||'/'||conversation_id::text||'/'||id::text||'/test.pdf','test.pdf','application/pdf',100
from public.messages where id in ('f5000000-0000-4000-8000-000000000001','f5000000-0000-4000-8000-000000000002');
set local role authenticated;
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000002',true);

select throws_ok($$select public.set_message_block('f2000000-0000-4000-8000-000000000004',true)$$,'22023','profile_not_available','Foreign tenant cannot be blocked');
select throws_ok($$select public.set_message_block('f2000000-0000-4000-8000-000000000002',true)$$,'22023','profile_not_available','Cannot block self');
select lives_ok($$select public.report_message('f5000000-0000-4000-8000-000000000001','Please check')$$,'Member reports one received message');
select lives_ok($$select public.report_message('f5000000-0000-4000-8000-000000000001','Please check again')$$,'Retry is idempotent');
select is((select count(*) from public.message_reports),1::bigint,'Report is deduplicated');
select lives_ok($$select public.set_message_block('f2000000-0000-4000-8000-000000000003',true)$$,'Block sender');
select is((select count(*) from public.messages),0::bigint,'Blocked sender hidden in direct and group messages');
select is((select count(*) from public.message_attachments),0::bigint,'Blocked attachment metadata is hidden');
select ok(not exists(select 1 from public.list_conversations() where last_message is not null),'List previews cannot leak blocked messages');
select ok(not private.can_access_message_attachment('f4000000-0000-4000-8000-000000000001','f5000000-0000-4000-8000-000000000001'),'Blocked attachment download is denied');
select throws_ok($$select public.send_message('f4000000-0000-4000-8000-000000000001','new message')$$,'42501','message_contact_blocked','Blocker cannot continue direct chat');
select throws_ok($$select public.resolve_message_report((select id from public.message_reports limit 1),true,'Removed')$$,'42501','permission_denied','Employee cannot moderate');
set local role authenticated;
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000003',true);

select is((select count(*) from public.message_reports),0::bigint,'Reported person cannot read private report');
select throws_ok($$select public.send_message('f4000000-0000-4000-8000-000000000001','new message')$$,'42501','message_contact_blocked','Blocked sender cannot continue direct chat');
select throws_ok($$insert into public.messages(organization_id,conversation_id,sender_id,body) values('f0000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000003','bypass')$$,'42501',null,'Direct insertion cannot bypass block');
select throws_ok($$select public.send_message('f4000000-0000-4000-8000-000000000002','kill yourself')$$,'22023','message_content_not_allowed','Content filter enforced by server');
select lives_ok($$select public.send_message('f4000000-0000-4000-8000-000000000002','Normal group message')$$,'Unrelated group members still receive ordinary messages');
set local role authenticated;
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000004',true);

select is((select count(*) from public.message_reports),0::bigint,'Other tenant admin cannot see reports');
select is((select count(*) from public.message_attachments),0::bigint,'Foreign admin cannot enumerate reported attachments');
select throws_ok($$select public.report_message('f5000000-0000-4000-8000-000000000001','Foreign report')$$,'42501','permission_denied','Other tenant cannot report guessed message');
set local role authenticated;
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000001',true);

select is((select count(*) from public.messages),0::bigint,'Admin is not granted general access to private conversations');
select is((select count(*) from public.message_reports),1::bigint,'Own tenant admin sees exactly reported content');
select throws_ok($$select public.report_message('f5000000-0000-4000-8000-000000000002','Not a member')$$,'42501','permission_denied','Nonmember admin cannot report unshared messages');
select ok(private.can_access_message_attachment('f4000000-0000-4000-8000-000000000001','f5000000-0000-4000-8000-000000000001'),'Own admin can inspect specifically reported attachments');
select is((select count(*) from public.message_attachments),1::bigint,'Nonmember admin can enumerate only the reported attachment');
select is((select message_id from public.message_attachments),'f5000000-0000-4000-8000-000000000001'::uuid,'Metadata belongs to the open report');
select ok(not private.can_access_message_attachment('f4000000-0000-4000-8000-000000000002','f5000000-0000-4000-8000-000000000002'),'Own admin cannot inspect other private attachments');
select lives_ok($$select public.resolve_message_report((select id from public.message_reports limit 1),true,'Policy violation removed')$$,'Admin may remove only a reported message');
select is((select count(*) from public.message_attachments),0::bigint,'Closing the report revokes nonmember attachment metadata access');
set local role authenticated;
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000002',true);

select lives_ok($$select public.set_message_block('f2000000-0000-4000-8000-000000000003',false)$$,'Unblock works');
select ok((select retracted_at is not null from public.messages where id='f5000000-0000-4000-8000-000000000001'),'Moderator removal persists');
select lives_ok($$select public.send_message('f4000000-0000-4000-8000-000000000001','Contact allowed again')$$,'Direct contact works after unblock');
select lives_ok($$select public.request_account_deletion()$$,'Employee initiates own deletion in app');
select lives_ok($$select public.request_account_deletion()$$,'Request retry does not create duplicates');
select is((select count(*) from public.account_deletion_requests),1::bigint,'Exactly one deletion request');
select ok((select due_at=requested_at+interval '7 days' from public.account_deletion_requests),'Deadline is seven days');
select throws_ok($$select public.complete_account_deletion_request((select id from public.account_deletion_requests), 'Reviewed data',true)$$,'42501','permission_denied','Employee cannot mark own request complete');
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000003',true);
select is((select count(*) from public.account_deletion_requests),0::bigint,'Other employee cannot see request');
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000004',true);
select is((select count(*) from public.account_deletion_requests),0::bigint,'Foreign admin cannot see request');
select ok(not private.can_access_message_attachment('f4000000-0000-4000-8000-000000000002','f5000000-0000-4000-8000-000000000002'),'Foreign admin cannot access unreported attachments');
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000001',true);
select is((select count(*) from public.account_deletion_requests),1::bigint,'Own admin sees queue');
select throws_ok($$select public.complete_account_deletion_request((select id from public.account_deletion_requests),'Reviewed data',true)$$,'22023','account_not_deleted','Cannot falsely mark live account deleted');
-- Simulate completed login deletion for this rolled-back fixture only.
reset role;
update public.profiles set auth_user_id=null,deleted_at=now(),status='archived' where id='f2000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.complete_account_deletion_request((select id from public.account_deletion_requests),'Reviewed data',false)$$,'22023','completion_evidence_required','Confirmation must have actually been sent');
select lives_ok($$select public.complete_account_deletion_request((select id from public.account_deletion_requests),'Fixture data removed; no retention; confirmation sent.',true)$$,'Completion may be recorded with deleted login and evidence');
select is((select status from public.account_deletion_requests),'completed','Request completion recorded');
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.request_account_deletion()$$,'42501','permission_denied','Stale JWT of deleted account cannot act');
select * from finish();
rollback;
